# Current language (module-level so all modules can access it)
_current_lang = "en"


def tr(key, **kwargs):
    """Translate a UI string to the current language.

    Returns the translation for the current language, falling back to
    English if the key is missing. Never crashes; returns the key
    itself as a last resort.

    Usage:
        tr("buttons.save")
        tr("status.classes_imported_count", n=5)
    """
    lang_dict = TRANSLATIONS.get(_current_lang, TRANSLATIONS["en"])
    text = lang_dict.get(key, TRANSLATIONS["en"].get(key, key))
    if kwargs:
        try:
            return text.format(**kwargs)
        except (KeyError, IndexError, ValueError):
            return text
    return text


def get_language():
    """Get the current language code."""
    return _current_lang


def set_language(lang):
    """Set the current language code."""
    global _current_lang
    if lang in TRANSLATIONS:
        _current_lang = lang


RTL_LANGUAGES = frozenset({"ar", "he", "fa", "ur"})


def is_rtl(lang=None):
    """Return True if the given (or current) language is right-to-left."""
    return (lang or _current_lang) in RTL_LANGUAGES
